import { forwardRef, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { Interactive, Sequence, random, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// Waves of quarter turns sweep the tile grid: `passes` scrambling waves, then
// a resolve wave that turns every tile still off its target, and with `loop`
// a wave back to the start. Frames on the 30 fps scene timeline, after
// `speed`. The ids are public: a saved `timing` prop refers to them.

type TruchetFlipElementId = `pass:${number}` | "resolve" | "back";

interface TruchetFlipTimingProps {
  passes?: number;
  loop?: boolean;
}

const LEAD = 6;
const SPREAD$own = 30;
const SNAP$own = 12;
const GAP = 24;
const RESOLVE_GAP = 30;
const HOLD = 18;
const LOOP_HOLD = 24;
const MAX_PASSES = 4;
const DEFAULT_PASSES = 2;

const finite$own = (value: number | undefined, fallback: number) =>
  typeof value === "number" && Number.isFinite(value) ? value : fallback;
const clamp$own = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

/** When each wave starts and how long the whole film runs. */
function truchetFlipPlan(options: TruchetFlipTimingProps = {}) {
  const requested = finite$own(options.passes, DEFAULT_PASSES);
  const passes = Math.round(clamp$own(requested, 0, MAX_PASSES));
  const starts = Array.from({ length: passes }, (_, i) => LEAD + i * GAP);
  const lastPass = LEAD + Math.max(0, passes - 1) * GAP;
  const resolveStart = passes === 0 ? LEAD : lastPass + RESOLVE_GAP;
  const settled = resolveStart + SPREAD$own + SNAP$own;
  const returnStart = settled + LOOP_HOLD;
  const loop = options.loop === true;
  const duration = loop ? returnStart + SPREAD$own + SNAP$own : settled + HOLD;
  return {
    passes,
    starts,
    resolveStart,
    settled,
    returnStart,
    loop,
    duration,
  };
}

// Each wave reaches the farthest tile `spread` frames after its start and
// every tile snaps round over `snap`. The passes are a chain, the resolve
// follows the last pass and the wave back follows the resolve.
const truchetFlipTimeline = defineTimeline<
  TruchetFlipElementId,
  TruchetFlipTimingProps
>((props) => {
  const plan = truchetFlipPlan(props);
  const beats = { spread: SPREAD$own, snap: SNAP$own };
  const elements: TimelineElement<TruchetFlipElementId>[] = plan.starts.map(
    (start, i) => ({
      id: `pass:${i}` as const,
      lane: "Waves",
      label: `Pass ${i + 1}`,
      start,
      length:
        (i + 1 < plan.passes ? plan.starts[i + 1] : plan.resolveStart) - start,
      follows: i > 0 ? (`pass:${i - 1}` as const) : undefined,
      beats,
    }),
  );
  elements.push({
    id: "resolve",
    lane: "Waves",
    label: "Resolve",
    start: plan.resolveStart,
    length: SPREAD$own + SNAP$own,
    follows: plan.passes > 0 ? `pass:${plan.passes - 1}` : undefined,
    beats,
  });
  if (plan.loop) {
    elements.push({
      id: "back",
      lane: "Waves",
      label: "Back to the start",
      start: plan.returnStart,
      length: SPREAD$own + SNAP$own,
      follows: "resolve",
      beats,
    });
  }
  return elements;
});

type TruchetFlipWaveMode = "radial" | "diagonal" | "random";
type TruchetFlipResolve = "rings" | "field" | "silhouette";
type TruchetFlipVariant = "stroke" | "filled";
type TruchetFlipOrientation = 0 | 1;

interface TruchetFlipProps {
  tiles?: number;
  weight?: number;
  passes?: number;
  waveMode?: TruchetFlipWaveMode;
  resolve?: TruchetFlipResolve;
  variant?: TruchetFlipVariant;
  color?: string;
  secondaryColor?: string;
  seed?: number;
  speed?: number;
  loop?: boolean;
  className?: string;
  /**
   * Moves, trims or stretches single waves, by the ids in `./timeline`.
   * Frames on the scene timeline, after `speed`.
   */
  timing?: Timing<TruchetFlipElementId>;
}

type Paint = "color" | "secondaryColor" | "className";
type Unset = "secondaryColor" | "className" | "timing";

interface TruchetFlipOptions extends Omit<TruchetFlipProps, Paint> {
  width?: number;
  height?: number;
  fps?: number;
}

interface TruchetFlipTile {
  col: number;
  row: number;
  x: number;
  y: number;
  alternate: boolean;
  initial: TruchetFlipOrientation;
  target: TruchetFlipOrientation;
  delay: number;
}

const truchetFlipDefaults: Required<Omit<TruchetFlipProps, Unset>> = {
  tiles: 10,
  weight: 0.2,
  passes: 2,
  waveMode: "radial",
  resolve: "rings",
  variant: "stroke",
  color: "#ffffff",
  seed: 1,
  speed: 1,
  loop: false,
};

const SPREAD = 30;
const SNAP = 12;
const SNAP_SETTLE = 8;
const SNAP_RISE = 4;
const SNAP_DAMPING = 0.65;
const MIN_TILES = 4;
const MAX_TILES = 24;
const MIN_WEIGHT = 0.04;
const MAX_WEIGHT = 0.34;
const SILHOUETTE = 0.38;
const OVERLAP = 0.75;
const SNAP_FREQUENCY = (Math.PI - Math.acos(SNAP_DAMPING)) / SNAP_RISE;
const SNAP_RATIO = SNAP_DAMPING / Math.sqrt(1 - SNAP_DAMPING ** 2);

const finite = (value: number | undefined, fallback: number) =>
  typeof value === "number" && Number.isFinite(value) ? value : fallback;
const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));
const round = (value: number) => Math.round(value * 1000) / 1000;
const isOdd = (value: number) => Math.abs(value % 2) === 1;
const turn = (wave: number) => (wave % 2 === 0 ? 1 : -1);
const rateOf = (speed: number | undefined) =>
  Math.max(0, finite(speed, truchetFlipDefaults.speed));
const waveOf = (value: string | undefined): TruchetFlipWaveMode =>
  value === "diagonal" || value === "random" ? value : "radial";
const resolveOf = (value: string | undefined): TruchetFlipResolve =>
  value === "field" || value === "silhouette" ? value : "rings";
const variantOf = (value: string | undefined): TruchetFlipVariant =>
  value === "filled" ? value : "stroke";

function smoothstep(value: number) {
  const t = clamp(value, 0, 1);
  return t * t * (3 - 2 * t);
}

function mazeKey(seed: number, col: number, row: number) {
  return random(`truchet-flip-${seed}-${col}-${row}`);
}

function waveKey(seed: number, col: number, row: number) {
  return random(`truchet-flip-${seed}-wave-${col}-${row}`);
}

function getTruchetFlipSnap(frames: number) {
  if (Number.isNaN(frames) || frames <= 0) return 0;
  if (frames >= SNAP) return 1;
  const phase = SNAP_FREQUENCY * frames;
  const decay = Math.exp(-SNAP_RATIO * phase);
  const ring = decay * (Math.cos(phase) + SNAP_RATIO * Math.sin(phase));
  const settle = smoothstep((frames - SNAP_SETTLE) / (SNAP - SNAP_SETTLE));
  return 1 - ring * (1 - settle);
}

const getTruchetFlipTimeline = truchetFlipPlan;

type TruchetFlipTimeline = ReturnType<typeof getTruchetFlipTimeline>;

const truchetFlipLength = getTruchetFlipTimeline().settled;

function getTruchetFlipDuration(options: TruchetFlipOptions = {}) {
  const rate = rateOf(options.speed);
  const { duration } = getTruchetFlipTimeline(options);
  return rate === 0 ? 1 : Math.max(1, Math.ceil(duration / rate));
}

/** One wave as the tiles read it: its start, its spread and its snap pace. */
interface TruchetFlipWave {
  start: number;
  /** Multiplies each tile's delay; 1 reaches the farthest tile in 30 frames. */
  spread: number;
  /** Multiplies the time a tile has snapped for; 1 snaps in 12 frames. */
  pace: number;
}

interface TruchetFlipWaves {
  passes: TruchetFlipWave[];
  resolve: TruchetFlipWave;
  back: TruchetFlipWave;
  /** Frames of one loop, when the film loops. */
  period: number;
}

/** The waves exactly as the plan places them. */
function getTruchetFlipWaves(
  timeline: TruchetFlipTimeline,
): TruchetFlipWaves {
  const at = (start: number) => ({ start, spread: 1, pace: 1 });
  return {
    passes: timeline.starts.map(at),
    resolve: at(timeline.resolveStart),
    back: at(timeline.returnStart),
    period: timeline.duration,
  };
}

function getTruchetFlipTime(
  frame: number,
  options: TruchetFlipOptions = {},
  period?: number,
) {
  const scale = 30 / Math.max(1, finite(options.fps, 30));
  const time = Math.max(0, finite(frame, 0)) * scale * rateOf(options.speed);
  const { duration, loop } = getTruchetFlipTimeline(options);
  return loop ? time % (period ?? duration) : time;
}

function getTruchetFlipTarget(
  resolve: TruchetFlipResolve,
  col: number,
  row: number,
  tiles = truchetFlipDefaults.tiles,
): TruchetFlipOrientation {
  if (resolve === "field") return 0;
  if (resolve === "silhouette") {
    const inside = Math.hypot(col + 0.5, row + 0.5) < tiles * SILHOUETTE;
    return inside && isOdd(col + row) ? 1 : 0;
  }
  const left = col < 0;
  const above = row < 0;
  return left === above ? 0 : 1;
}

function getTruchetFlipGrid(options: TruchetFlipOptions = {}) {
  const width = Math.max(1, finite(options.width, 1280));
  const height = Math.max(1, finite(options.height, 720));
  const requested = finite(options.tiles, truchetFlipDefaults.tiles);
  const count = Math.round(clamp(requested, MIN_TILES, MAX_TILES));
  const size = Math.min(width, height) / count;
  const halfCols = Math.ceil(width / 2 / size - 1e-6);
  const halfRows = Math.ceil(height / 2 / size - 1e-6);
  const seed = finite(options.seed, truchetFlipDefaults.seed);
  const mode = waveOf(options.waveMode);
  const resolve = resolveOf(options.resolve);
  const cells: { col: number; row: number }[] = [];
  for (let row = -halfRows; row < halfRows; row++) {
    for (let col = -halfCols; col < halfCols; col++) cells.push({ col, row });
  }
  const ranks: number[] = [];
  if (mode === "random") {
    const keys = cells.map(({ col, row }) => waveKey(seed, col, row));
    const order = keys.map((_, index) => index);
    order.sort((a, b) => keys[a] - keys[b]);
    for (const [position, index] of order.entries()) ranks[index] = position;
  }
  const shift = halfCols + halfRows;
  const diagonals = 2 * (shift - 1);
  const nearest = Math.hypot(0.5, 0.5);
  const farthest = Math.hypot(halfCols - 0.5, halfRows - 0.5);
  const delayOf = (col: number, row: number, index: number) => {
    if (mode === "random") {
      return (SPREAD * ranks[index]) / (cells.length - 1);
    }
    if (mode === "diagonal") {
      return (SPREAD * (col + row + shift)) / diagonals;
    }
    const distance = Math.hypot(col + 0.5, row + 0.5) - nearest;
    return (SPREAD * distance) / Math.max(1e-6, farthest - nearest);
  };
  const tiles: TruchetFlipTile[] = cells.map(({ col, row }, index) => ({
    col,
    row,
    x: round(width / 2 + (col + 0.5) * size),
    y: round(height / 2 + (row + 0.5) * size),
    alternate: isOdd(col + row),
    initial: mazeKey(seed, col, row) < 0.5 ? 0 : 1,
    target: getTruchetFlipTarget(resolve, col, row, count),
    delay: round(clamp(delayOf(col, row, index), 0, SPREAD)),
  }));
  return {
    width,
    height,
    count,
    size,
    unit: Math.min(width, height) / 720,
    tiles,
  };
}

type TruchetFlipGrid = ReturnType<typeof getTruchetFlipGrid>;

function getTruchetFlipAngle(
  tile: TruchetFlipTile,
  time: number,
  timeline: TruchetFlipTimeline,
  waves: TruchetFlipWaves = getTruchetFlipWaves(timeline),
) {
  const snapOf = (wave: TruchetFlipWave) =>
    getTruchetFlipSnap(
      (time - wave.start - tile.delay * wave.spread) * wave.pace,
    );
  let turns = 0;
  for (const [index, wave] of waves.passes.entries()) {
    turns += turn(index) * snapOf(wave);
  }
  const reached = (tile.initial + timeline.passes) % 2;
  if (reached !== tile.target) {
    turns += turn(timeline.passes) * snapOf(waves.resolve);
  }
  if (timeline.loop && tile.target !== tile.initial) {
    turns += turn(timeline.passes + 1) * snapOf(waves.back);
  }
  return (tile.initial + turns) * 90;
}

function getTruchetFlipTilePath(
  size: number,
  variant: TruchetFlipVariant = "stroke",
  overlap = OVERLAP,
) {
  const half = Math.max(0, finite(size, 0)) / 2;
  const pad = clamp(finite(overlap, OVERLAP), 0, half / 4);
  const radius = `${round(half)} ${round(half)}`;
  const point = (x: number, y: number) => `${round(x)} ${round(y)}`;
  if (variant === "filled") {
    const reach = Math.sqrt(half * half - pad * pad);
    const sector = (cx: number, cy: number, side: number) => {
      const corner = point(cx - side * pad, cy - side * pad);
      const start = point(cx + side * reach, cy - side * pad);
      const end = point(cx - side * pad, cy + side * reach);
      return `M ${corner} L ${start} A ${radius} 0 0 1 ${end} Z`;
    };
    return `${sector(-half, -half, 1)} ${sector(half, half, -1)}`;
  }
  const bend = half > 0 ? pad / half : 0;
  const cos = half * Math.cos(bend);
  const sin = half * Math.sin(bend);
  const arc = (cx: number, cy: number, side: number) => {
    const start = point(cx + side * cos, cy - side * sin);
    const end = point(cx - side * sin, cy + side * cos);
    return `M ${start} A ${radius} 0 0 1 ${end}`;
  };
  return `${arc(-half, -half, 1)} ${arc(half, half, -1)}`;
}

function getTruchetFlipState(
  frame: number,
  options: TruchetFlipOptions = {},
  grid: TruchetFlipGrid = getTruchetFlipGrid(options),
  waves?: TruchetFlipWaves,
) {
  const timeline = getTruchetFlipTimeline(options);
  const placed = waves ?? getTruchetFlipWaves(timeline);
  const time = getTruchetFlipTime(frame, options, placed.period);
  const variant = variantOf(options.variant);
  const requested = finite(options.weight, truchetFlipDefaults.weight);
  const weight = clamp(requested, MIN_WEIGHT, MAX_WEIGHT);
  return {
    ...grid,
    time,
    timeline,
    variant,
    strokeWidth: round(grid.size * weight),
    path: getTruchetFlipTilePath(grid.size, variant, OVERLAP * grid.unit),
    tiles: grid.tiles.map((tile) => {
      const angle = getTruchetFlipAngle(tile, time, timeline, placed);
      const rotation = round(angle);
      const transform = `translate(${tile.x} ${tile.y}) rotate(${rotation})`;
      return { ...tile, angle, transform };
    }),
  };
}

/** A scheduled wave as the tiles read it. */
const waveOfElement = (e: ResolvedElement<TruchetFlipElementId>) => ({
  start: e.start,
  spread: e.beat("spread") / SPREAD,
  pace: SNAP / e.beat("snap"),
});

function TruchetFlipBase(props: TruchetFlipProps) {
  const {
    tiles = truchetFlipDefaults.tiles,
    weight = truchetFlipDefaults.weight,
    passes = truchetFlipDefaults.passes,
    waveMode = truchetFlipDefaults.waveMode,
    resolve = truchetFlipDefaults.resolve,
    variant = truchetFlipDefaults.variant,
    color = truchetFlipDefaults.color,
    secondaryColor,
    seed = truchetFlipDefaults.seed,
    speed = truchetFlipDefaults.speed,
    loop = truchetFlipDefaults.loop,
    className,
    timing,
  } = props;
  const frame = useSceneFrame();
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    truchetFlipTimeline,
    props,
    durationInFrames * rateOf(speed),
    timing,
  );
  const grid = useMemo(() => {
    const layout = { width, height, tiles, seed, waveMode, resolve };
    return getTruchetFlipGrid(layout);
  }, [width, height, tiles, seed, waveMode, resolve]);
  const motion = { fps, weight, passes, variant, speed, loop };
  const plan = getTruchetFlipTimeline(motion);
  const resolveWave = waveOfElement(tl.get("resolve"));
  const back = plan.loop ? tl.get("back") : undefined;
  const waves: TruchetFlipWaves = {
    passes: plan.starts.map((_, i) => waveOfElement(tl.get(`pass:${i}`))),
    resolve: resolveWave,
    back: back ? waveOfElement(back) : resolveWave,
    period: back ? back.end : plan.duration,
  };
  const state = getTruchetFlipState(frame, motion, grid, waves);
  const filled = state.variant === "filled";
  const primary = state.tiles.filter((tile) => !tile.alternate);
  const alternate = state.tiles.filter((tile) => tile.alternate);
  const layers = [
    { key: "primary", paint: color, tiles: primary },
    { key: "alternate", paint: secondaryColor ?? color, tiles: alternate },
  ];

  return (
    <div
      className={className}
      style={{ position: "absolute", inset: 0, overflow: "hidden" }}
    >
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-label="Truchet tile pattern"
        style={{ display: "block" }}
      >
        {layers.map((layer) => (
          <g
            key={layer.key}
            fill={filled ? layer.paint : "none"}
            stroke={filled ? "none" : layer.paint}
            strokeWidth={filled ? undefined : state.strokeWidth}
          >
            {layer.tiles.map((tile) => (
              <path
                key={`${tile.col}:${tile.row}`}
                d={state.path}
                transform={tile.transform}
              />
            ))}
          </g>
        ))}
      </svg>
    </div>
  );
}

