const ELEMENT_PROP_KEYS = new Set(["tiles","weight","passes","waveMode","resolve","variant","color","secondaryColor","seed","loop","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  tiles: 10,
  weight: 0.2,
  passes: 2,
  waveMode: "radial",
  resolve: "rings",
  variant: "stroke",
